    private LoomIconSet() { }
    static boolean draw(GuiGraphics g,int x,int y,int size,LoomButton.Icon icon,int color) {
        String[] rows=SHAPES.get(icon); if(rows==null)return false;
        for(int row=0;row<16;row++)for(int col=0;col<16;col++) {
            char cell=rows[row].charAt(col); if(cell=='.')continue;
            int left=x+col*size/16,top=y+row*size/16;
            int right=x+(col+1)*size/16,bottom=y+(row+1)*size/16;
            if(right>left&&bottom>top)g.fill(left,top,right,bottom,cell=='a'&&color==LoomUiTheme.TEXT?LoomUiTheme.ACCENT:color);
        }
        return true;
    }
